PRAGMA foreign_keys=ON;
CREATE TABLE merchant_users(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchants(id),email TEXT NOT NULL,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,password_iterations INTEGER NOT NULL DEFAULT 210000,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('invited','active','suspended','disabled')),display_name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,email),UNIQUE(merchant_id,id));
CREATE TABLE merchant_user_sessions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,csrf_hash TEXT NOT NULL,expires_at TEXT NOT NULL,last_seen_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id,user_id) REFERENCES merchant_users(merchant_id,id));
CREATE TABLE merchant_roles(id TEXT PRIMARY KEY,merchant_id TEXT,code TEXT NOT NULL,name TEXT NOT NULL,is_system INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,code));
CREATE TABLE merchant_permissions(code TEXT PRIMARY KEY,module TEXT NOT NULL,description TEXT NOT NULL);
CREATE TABLE merchant_role_permissions(role_id TEXT NOT NULL REFERENCES merchant_roles(id),permission_code TEXT NOT NULL REFERENCES merchant_permissions(code),PRIMARY KEY(role_id,permission_code));
CREATE TABLE merchant_user_roles(merchant_id TEXT NOT NULL,user_id TEXT NOT NULL,role_id TEXT NOT NULL REFERENCES merchant_roles(id),PRIMARY KEY(user_id,role_id),FOREIGN KEY(merchant_id,user_id) REFERENCES merchant_users(merchant_id,id));
CREATE TABLE merchant_login_attempts(rate_key TEXT NOT NULL,bucket_start TEXT NOT NULL,attempt_count INTEGER NOT NULL DEFAULT 0,last_attempt_at TEXT,PRIMARY KEY(rate_key,bucket_start));
CREATE TABLE merchant_security_events(id TEXT PRIMARY KEY,merchant_id TEXT,user_id TEXT,action TEXT NOT NULL,metadata TEXT NOT NULL DEFAULT '{}',ip_hash TEXT,user_agent_hash TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_password_reset_tokens(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id,user_id) REFERENCES merchant_users(merchant_id,id));
CREATE TABLE platform_plans(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'disabled',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE platform_modules(code TEXT PRIMARY KEY,name TEXT NOT NULL,provider_required INTEGER NOT NULL DEFAULT 0);
CREATE TABLE plan_entitlements(plan_id TEXT NOT NULL REFERENCES platform_plans(id),module_code TEXT NOT NULL REFERENCES platform_modules(code),enabled INTEGER NOT NULL DEFAULT 0,limits_json TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(plan_id,module_code));
CREATE TABLE merchant_subscriptions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL UNIQUE REFERENCES merchants(id),plan_id TEXT NOT NULL REFERENCES platform_plans(id),status TEXT NOT NULL CHECK(status IN('trial','active','past_due','suspended','cancelled')),starts_at TEXT NOT NULL,ends_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_module_overrides(merchant_id TEXT NOT NULL REFERENCES merchants(id),module_code TEXT NOT NULL REFERENCES platform_modules(code),enabled INTEGER NOT NULL,reason TEXT,expires_at TEXT,PRIMARY KEY(merchant_id,module_code));
CREATE TABLE merchant_usage_counters(merchant_id TEXT NOT NULL,module_code TEXT NOT NULL,period_key TEXT NOT NULL,usage_count INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(merchant_id,module_code,period_key));
CREATE INDEX idx_merchant_sessions_user ON merchant_user_sessions(merchant_id,user_id,expires_at);
